DROP TABLE IF EXISTS `bird_species`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bird_species` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `avibase_id` varchar(300) DEFAULT NULL,
  `common_name` varchar(300) NOT NULL,
  `order` varchar(300) DEFAULT NULL,
  `order_common` varchar(300) DEFAULT NULL,
  `family` varchar(300) DEFAULT NULL,
  `family_common` varchar(300) DEFAULT NULL,
  `genus` varchar(300) DEFAULT NULL,
  `genus_common` varchar(300) DEFAULT NULL,
  `species` varchar(300) DEFAULT NULL,
  `bird_details` varchar(10000) DEFAULT NULL,
  `img_path` varchar(1000) DEFAULT NULL,
  `rarity` varchar(300) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`),
  UNIQUE KEY `common_name` (`common_name`),
  UNIQUE KEY `avibase_id` (`avibase_id`)
) ENGINE=InnoDB AUTO_INCREMENT=13932 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

